diff_hunks.new_code:
server.tool(
    "list_directory",
    "Get a detailed listing of all files and directories in a specified path. Results clearly distinguish between files and directories with [FILE] and [DIR] prefixes.",
    {
        path: z.string().describe("The path to the directory"),
        showHidden: z.boolean().optional().default(false).describe("Show hidden files starting with ."),
        sortBy: z.enum(["default", "name", "type"]).optional().default("default").describe("Sorting mode: default (directories first), name, or type"),
        reverse: z.boolean().optional().default(false).describe("Reverse the sort order")
    },
    async ({ path: dirPath, showHidden, sortBy, reverse }) => {
        try {
            const resolvedPath = await resolvePath(dirPath);
            const entries = await fs.readdir(resolvedPath, { withFileTypes: true });

            // 숨김 파일 필터링
            const filteredEntries = showHidden
                ? entries
                : entries.filter(entry => !entry.name.startsWith('.'));

            const getEntryTypeOrder = (entry) => {
                if (entry.isDirectory()) return 0;
                if (entry.isSymbolicLink()) return 1;
                return 2;
            };

            // 기존 동작을 유지하면서 선택적 정렬 방식 지원
            const sortedEntries = [...filteredEntries].sort((a, b) => {
                if (sortBy === "name") {
                    return a.name.localeCompare(b.name);
                }

                if (sortBy === "type") {
                    const typeDiff = getEntryTypeOrder(a) - getEntryTypeOrder(b);
                    if (typeDiff !== 0) return typeDiff;
                    return a.name.localeCompare(b.name);
                }

                // default: 디렉토리 먼저, 그 다음 파일 순으로 정렬
                if (a.isDirectory() && !b.isDirectory()) return -1;
                if (!a.isDirectory() && b.isDirectory()) return 1;
                return a.name.localeCompare(b.name);
            });

            if (reverse) {
                sortedEntries.reverse();
            }

            const formatted = sortedEntries
                .map((entry) => {
                    let prefix = entry.isDirectory() ? "[DIR]" : "[FILE]";
                    if (entry.isSymbolicLink()) prefix = "[LINK]";
                    return `${prefix} ${entry.name}`;
                })
                .join("\n");

            return {
                content: [{
                    type: "text",
                    text: formatted || "Empty directory"
                }]
            };
        } catch (error) {
            return {
                content: [{ type: "text", text: `Error: ${error.message}` }],
                isError: true
            };
        }
    }
);

