async requestPlanning(originalRequest, tasks, splitDetails) {
    await this.loadTasks();
    const normalizedOriginalRequest = originalRequest.trim();
    const normalizedSplitDetails = splitDetails.trim();
    const normalizedTasks = tasks.map((taskDef) => ({
        title: taskDef.title.trim(),
        description: taskDef.description.trim(),
    }));
    const seenTitles = new Set();
    for (const taskDef of normalizedTasks) {
        const normalizedTitle = taskDef.title.toLocaleLowerCase();
        if (seenTitles.has(normalizedTitle)) {
            return {
                status: "error",
                message: "Task titles must be unique within a request.",
            };
        }
        seenTitles.add(normalizedTitle);
    }
    this.requestCounter += 1;
    const requestId = `req-${this.requestCounter}`;
    const newTasks = [];
    for (const taskDef of normalizedTasks) {
        this.taskCounter += 1;
        newTasks.push({
            id: `task-${this.taskCounter}`,
            title: taskDef.title,
            description: taskDef.description,
            done: false,
            approved: false,
            completedDetails: "",
        });
    }
    this.data.requests.push({
        requestId,
        originalRequest: normalizedOriginalRequest,
        splitDetails: normalizedSplitDetails,
        tasks: newTasks,
        completed: false,
    });
    await this.saveTasks();
    const progressTable = this.formatTaskProgressTable(requestId);
    return {
        status: "planned",
        requestId,
        totalTasks: newTasks.length,
        tasks: newTasks.map((t) => ({
            id: t.id,
            title: t.title,
            description: t.description,
        })),
        message: `Tasks have been successfully added. Please use 'get_next_task' to retrieve the first task.\n${progressTable}`,
    };
}

