diff_hunks.new_code:
// 贷款月供计算工具
const loanPaymentTool = {
    name: "loan_payment",
    definition: {
        title: "贷款月供计算",
        description: "计算等额本息贷款的月供金额",
        inputSchema: {
            loan_amount: z.number().positive().describe("贷款本金"),
            annual_rate: z.number().positive().describe("年利率（小数形式）"),
            years: z.number().positive().describe("贷款年限"),
            payment_frequency: z.number().int().positive().default(12).describe("每年还款次数（默认12，12=按月，4=按季，1=按年）"),
            extra_payment: z.number().min(0).default(0).describe("每期额外还款金额（默认0）"),
            include_schedule: z.boolean().default(false).describe("是否包含简要还款进度摘要")
        }
    },
    handler: async ({ loan_amount, annual_rate, years, payment_frequency = 12, extra_payment = 0, include_schedule = false }) => {
        const periodRate = annual_rate / payment_frequency;
        const totalPayments = years * payment_frequency;
        const paymentLabel = payment_frequency === 12 ? "月供金额" : `每期还款金额（每年 ${payment_frequency} 次）`;
        if (periodRate === 0) {
            const basePayment = loan_amount / totalPayments;
            const actualPayment = basePayment + extra_payment;
            const actualPeriods = extra_payment > 0 ? Math.ceil(loan_amount / actualPayment) : totalPayments;
            const totalAmount = extra_payment > 0 ? Math.min(actualPayment * actualPeriods, loan_amount) : loan_amount;
            const scheduleSummary = include_schedule
                ? `\n预计还清期数：${actualPeriods}\n提前还清：${actualPeriods < totalPayments ? '是' : '否'}`
                : "";
            return createSuccessResponse(`贷款月供计算结果（零利率）：\n` +
                `贷款本金：${loan_amount.toFixed(2)}\n` +
                `贷款年限：${years} 年\n` +
                `还款频率：每年 ${payment_frequency} 次\n` +
                `${paymentLabel}：${basePayment.toFixed(2)}\n` +
                `每期额外还款：${extra_payment.toFixed(2)}\n` +
                `实际每期还款：${actualPayment.toFixed(2)}\n` +
                `总还款额：${totalAmount.toFixed(2)}` +
                scheduleSummary);
        }
        const basePayment = loan_amount * (periodRate * Math.pow(1 + periodRate, totalPayments)) /
            (Math.pow(1 + periodRate, totalPayments) - 1);
        const actualPayment = basePayment + extra_payment;
        let balance = loan_amount;
        let actualPeriods = 0;
        let totalAmount = 0;
        let totalInterest = 0;
        while (balance > 1e-8 && actualPeriods < totalPayments * 10) {
            const interestPortion = balance * periodRate;
            let principalPortion = actualPayment - interestPortion;
            if (principalPortion <= 0) {
                return createErrorResponse("每期还款金额不足以覆盖利息，贷款余额将无法减少！");
            }
            if (principalPortion > balance) {
                principalPortion = balance;
            }
            const paymentThisPeriod = interestPortion + principalPortion;
            balance -= principalPortion;
            totalAmount += paymentThisPeriod;
            totalInterest += interestPortion;
            actualPeriods++;
            if (actualPeriods >= totalPayments && extra_payment === 0) {
                break;
            }
        }
        const scheduleSummary = include_schedule
            ? `\n预计还清期数：${actualPeriods}\n原计划期数：${totalPayments}\n提前还清：${actualPeriods < totalPayments ? '是' : '否'}`
            : "";
        return createSuccessResponse(`贷款月供计算结果：\n` +
            `贷款本金：${loan_amount.toFixed(2)}\n` +
            `年利率：${(annual_rate * 100).toFixed(4)}%\n` +
            `贷款年限：${years} 年（${totalPayments} 期）\n` +
            `还款频率：每年 ${payment_frequency} 次\n` +
            `${paymentLabel}：${basePayment.toFixed(2)}\n` +
            `每期额外还款：${extra_payment.toFixed(2)}\n` +
            `实际每期还款：${actualPayment.toFixed(2)}\n` +
            `总还款额：${totalAmount.toFixed(2)}\n` +
            `总利息：${totalInterest.toFixed(2)}` +
            scheduleSummary);
    }
};

