diff_hunks.new_code:
async createEntities(entities, options = {}) {
    const graph = await this.loadGraph();
    const { allowOverwrite = false, defaultEntityType = "", defaultObservations = [] } = options;
    const now = new Date().toISOString();
    const createdOrUpdatedEntities = [];
    entities.forEach(e => {
        const normalizedEntity = {
            ...e,
            entityType: e.entityType ?? defaultEntityType,
            observations: e.observations ?? defaultObservations
        };
        const existingIndex = graph.entities.findIndex(existingEntity => existingEntity.name === normalizedEntity.name);
        if (existingIndex === -1) {
            const newEntity = {
                ...normalizedEntity,
                createdAt: now,
                version: normalizedEntity.version || 1
            };
            graph.entities.push(newEntity);
            createdOrUpdatedEntities.push(newEntity);
            return;
        }
        if (allowOverwrite) {
            const existingEntity = graph.entities[existingIndex];
            const updatedEntity = {
                ...existingEntity,
                ...normalizedEntity,
                createdAt: now,
                version: (existingEntity.version || 1) + 1
            };
            graph.entities[existingIndex] = updatedEntity;
            createdOrUpdatedEntities.push(updatedEntity);
        }
    });
    await this.saveGraph(graph);
    return createdOrUpdatedEntities;
}

