diff_hunks.new_code:
async createRelations(relations, options = {}) {
    const graph = await this.loadGraph();
    const { skipDuplicates = true, requireExistingEntities = false } = options;
    if (requireExistingEntities) {
        const entityNames = new Set(graph.entities.map(entity => entity.name));
        const missingEntities = relations.flatMap(relation => {
            const missing = [];
            if (!entityNames.has(relation.from)) {
                missing.push(relation.from);
            }
            if (!entityNames.has(relation.to)) {
                missing.push(relation.to);
            }
            return missing;
        });
        const uniqueMissingEntities = [...new Set(missingEntities)];
        if (uniqueMissingEntities.length > 0) {
            throw new Error(`Cannot create relations because these entities do not exist: ${uniqueMissingEntities.join(", ")}`);
        }
    }
    const newRelations = skipDuplicates
        ? relations.filter(r => !graph.relations.some(existingRelation => existingRelation.from === r.from &&
            existingRelation.to === r.to &&
            existingRelation.relationType === r.relationType))
        : relations;
    graph.relations.push(...newRelations);
    await this.saveGraph(graph);
    return newRelations;
}

