async createEntities(entities, context, location, options = {}) {
    const { mergeObservations = false, trimWhitespace = false, caseSensitive = true } = options;
    const normalizeValue = (value) => trimWhitespace ? value.trim() : value;
    const normalizeNameForCompare = (value) => {
        const normalized = normalizeValue(value);
        return caseSensitive ? normalized : normalized.toLowerCase();
    };
    const normalizedEntities = entities.map(entity => ({
        ...entity,
        name: normalizeValue(entity.name),
        entityType: normalizeValue(entity.entityType),
        observations: entity.observations.map(obs => normalizeValue(obs))
            .filter(obs => obs !== "")
    }));
    const graph = await this.loadGraph(context, location);
    const createdEntities = [];
    for (const entity of normalizedEntities) {
        const existingEntity = graph.entities.find(existing => normalizeNameForCompare(existing.name) === normalizeNameForCompare(entity.name));
        if (!existingEntity) {
            graph.entities.push(entity);
            createdEntities.push(entity);
            continue;
        }
        if (mergeObservations) {
            const newObservations = entity.observations.filter(obs => !existingEntity.observations.includes(obs));
            existingEntity.observations.push(...newObservations);
        }
    }
    await this.saveGraph(graph, context, location);
    return createdEntities;
}

