async handleOrderCoffee(productName, spec, quantity = 1, note = "") {
    const targetProduct = PRODUCTS.find(p => p.name === productName);
    if (!targetProduct) {
        throw new Error(`未找到商品：${productName}`);
    }
    if (!targetProduct.specs.includes(spec)) {
        throw new Error(`商品 ${productName} 不支持规格 ${spec}，支持的规格：${targetProduct.specs.join(" / ")}`);
    }
    const normalizedQuantity = Number.isInteger(quantity) ? quantity : parseInt(String(quantity), 10);
    if (!Number.isFinite(normalizedQuantity) || normalizedQuantity <= 0) {
        throw new Error("quantity 必须是大于 0 的整数");
    }
    const cleanedNote = typeof note === "string" ? note.trim() : "";
    const totalPrice = targetProduct.price * normalizedQuantity;
    let responseText = `### 下单成功 ✅\n\n` +
        `**商品**：${productName}\n` +
        `**规格**：${spec}\n` +
        `**数量**：${normalizedQuantity}杯\n` +
        `**单价**：${targetProduct.price}元\n` +
        `**总价**：${totalPrice}元\n` +
        `**特色**：${targetProduct.description}\n`;
    if (cleanedNote) {
        responseText += `**备注**：${cleanedNote}\n`;
    }
    responseText += `\n请使用下方二维码完成付款：`;
    return {
        content: [
            {
                type: "text",
                text: responseText
            },
            {
                type: "resource_link",
                name: "付款二维码",
                uri: PAYMENT_QR_URL
            }
        ]
    };
}

