server.tool("getComponentIndex", "Provides a categorized index of Magic UI components with example coverage counts to help clients discover the most relevant category tool before fetching full implementation details.", {}, async () => {
    try {
        const [components, allExampleComponents] = await Promise.all([
            fetchUIComponents(),
            fetchExampleComponents(),
        ]);
        const exampleNamesByComponent = buildExampleComponentMap(allExampleComponents);
        const categorizedIndex = Object.entries(componentCategories).map(([category, categoryComponents]) => ({
            category,
            components: categoryComponents
                .map((componentName) => {
                const component = components.find((c) => c.name === componentName);
                if (!component) {
                    return null;
                }
                const exampleNames = exampleNamesByComponent.get(componentName) || [];
                return {
                    name: component.name,
                    type: component.type,
                    description: component.description,
                    exampleCount: exampleNames.length,
                    examples: exampleNames,
                };
            })
                .filter((component) => component !== null),
        }));
        const uncategorizedComponents = components.filter((component) => !Object.values(componentCategories).some((categoryComponents) => categoryComponents.includes(component.name)));
        return {
            content: [
                {
                    type: "text",
                    text: JSON.stringify({
                        categories: categorizedIndex,
                        uncategorized: uncategorizedComponents,
                    }, null, 2),
                },
            ],
        };
    }
    catch (error) {
        return {
            content: [
                {
                    type: "text",
                    text: "Failed to build Magic UI component index",
                },
            ],
            isError: true,
        };
    }
});

