/**
 * docuking_push 입력 정규화
 * - filePath(구형) → filePaths(신형) 호환
 * - filePaths가 1개일 때 기존 handlePush(filePath) 호출 방식 유지
 */
function normalizePushArgs(args) {
  const normalized = { ...(args || {}) };

  if (!normalized.filePaths && normalized.filePath) {
    normalized.filePaths = [normalized.filePath];
  }

  if (Array.isArray(normalized.filePaths)) {
    const cleaned = normalized.filePaths
      .filter((p) => typeof p === 'string')
      .map((p) => p.trim())
      .filter(Boolean);

    normalized.filePaths = cleaned.length > 0 ? cleaned : undefined;
  }

  if (normalized.filePaths && normalized.filePaths.length === 1) {
    normalized.filePath = normalized.filePaths[0];
  } else {
    delete normalized.filePath;
  }

  return normalized;
}

