                                text: `Error: A project with the name "${name.trim()}" already exists. Please choose a different name.`
                            }],
                        isError: true
                    };
                }
                const metadataLines = [];
                if (repoUrl) {
                    metadataLines.push(`Repository: ${repoUrl.trim()}`);
                }
                if (normalizedTags && normalizedTags.length > 0) {
                    metadataLines.push(`Tags: ${normalizedTags.join(', ')}`);
                }
                const finalDescription = metadataLines.length > 0
                    ? `${description.trim()}\n\n${metadataLines.join('\n')}`
                    : description.trim();
                const now = new Date().toISOString();
                const project = {
                    id: randomUUID(),
                    name: name.trim(),
                    description: finalDescription,
                    createdAt: now,
                    updatedAt: now
                };
                const createdProject = await storage.createProject(project);
                return {
                    content: [{
                            type: 'text',
                            text: `✅ Project created successfully!

**${createdProject.name}** (ID: ${createdProject.id})
