            return `WITH SNIPPET (${withClause.fields?.join(', ')})`;
        case "DATA CATEGORY":
        case "DIVISION":
        case "NETWORK":
        case "PRICEBOOKID":
            return `WITH ${withClause.type} = ${withClause.value}`;
        case "METADATA":
        case "SECURITY_ENFORCED":
            return `WITH ${withClause.type}`;
